"""Authored mathematical records after reading all four complete Codex files.

The functions only expand source locators and serialize the authored decisions.
They do not choose claims, classifications or verdicts from textual patterns.
The Codex notes are leads and create no NOTES_INDEX verdict rows.
"""
from pathlib import Path
from datetime import datetime, timezone
import json, csv

OUT = Path(__file__).resolve().parents[1]
ROOT = OUT.parents[2]
PAGES = json.loads((ROOT/'work/pages.json').read_text())
TEXT = {k:(ROOT/f'sources/texts/codex/K34-{k:02}_transcription.tex').read_text() for k in range(5,9)}
items=[]; claims=[]; problems=[]; readings=[]; events=[]; links=[]; searches=[]
WHO='GPT-6 Astra Pro; configured effort not exposed; SA13 part 2/p4'
DATE='2026-11-19'

def L(k,a,b):
    f=f'codex/K34-{k:02}_transcription.tex'
    return [dict(file=f,cote=34,scan=int(p['scan']),start=max(a,p['start']),end=min(b,p['end']))
            for p in PAGES if p['file']==f and p['start']<=b and p['end']>=a]

def pos(locations):
    ls=[l for k,a,b in locations for l in L(k,a,b)]
    return dict(cote=[34],scans=list(dict.fromkeys(f"34:{l['scan']:03d}" for l in ls)),lines=ls)

def I(n,title,kind,locations,quote,statement,reconstruction,check='agrees',reason=None):
    assert any(quote in '\n'.join(TEXT[k].splitlines()[a-1:b]) for k,a,b in locations), (n,quote)
    items.append(dict(id=f'SA13-{n}',sources=[f'codex/K34-{k:02}_notes.md' for k in dict.fromkeys(x[0] for x in locations)],
        kind=kind,**pos(locations),his_words=quote,statement=statement,reconstruction=reconstruction,
        check=check,check_reason=reason or 'Checked against the whole passage, including deletions and additions; the Codex notes are leads, not additional authorial assertions.',title=title))

def C(n,item,locations,quote,statement,status,cls,fate,refs,search,proof=None,confidence='high',date=None):
    assert any(quote in '\n'.join(TEXT[k].splitlines()[a-1:b]) for k,a,b in locations), (n,quote)
    claims.append(dict(id=f'C-SA13-{n}',items=[f'SA13-{x}' for x in ([item] if isinstance(item,int) else item)],
        **pos(locations),his_statement=quote,statement=statement,status_on_pages=status,
        computation=proof or 'No numerical computation is required. The stated source and hypothesis comparison are recorded in proof_audit.md, Codex sections.',
        **{'class':cls},fate=fate,fate_date=date or 'The leaves carry no written date. SGA7 seminar1967–1969; volumeI published1972 andII1973. Later dates are stated with each reference; assessment19November2026.',
        present_status='As of 19 November 2026: '+fate,refs=refs,confidence=confidence,search_ids=search,
        computation_base='shards/p4/',
        authorship='Grothendieck manuscript; later attribution specified in the fate, including Deligne’s published résumé where applicable.'))

T='Let S be a strictly henselian trait, with residue characteristic exponent p, generic field K and separable closure Kbar; let ℓ≠p and Λν=Z/ℓ^(ν+1). '
SG=['P4_SGA7IIntro']; IL=['P4_Illusie2021']; PU=['P4_Riou2014']; LO=['P4_Nakayama1998','P4_IllusieLog2002']

# K34-05: comparison, both cycle conventions, and the geometric monodromy programme.
I(477,'Geometric generic fibre and strictly local base changes','other',[(5,17,64)],r'K_\alpha',
  T+'For proper X/S, geometric generic cohomology is the filtered colimit over finite extensions of K. Normalization gives strictly local valuation bases with purely inseparable special residue extensions, so proper base change identifies the cohomology of X and each base change with that of Xs.',
  'The bar on Kα in (1.3) is a reading alarm; the filtered terms must use Kα itself. Finiteness of integral normalization requires the usual finite/excellent setting or the optional complete base; the étale comparison uses the henselian valuation bases.')
C(800,477,[(5,19,37)],r'\varinjlim_\alpha',T+'For X of finite type, H^i(X_Kbar,Λν)=colimα H^i(X_Kα,Λν), with finite Kα⊂Kbar and affine transition maps.','proof sketched','E',
  'Established continuity of étale cohomology; Illusie2021 §1.1.4 gives the strict-local geometric-fibre calculation used here. The extra bar in the manuscript term is incompatible with this indexing construction.',IL,['P4-S17'])
C(801,477,[(5,33,64)],'radicielle',T+'The special-fibre change induced by a purely inseparable residue extension is a universal homeomorphism and gives equivalent étale topoi; proper base change over a strictly henselian base gives H*(X,Λν)≅H*(Xs,Λν) and the compatible identifications after finite base change.','proof sketched','E',
  'These are the proper-base-change and topological-invariance ingredients of the later nearby-cycle construction, explicitly used in SGA7 I§2 and Illusie2021 §1.2. No arbitrary-base invariance is asserted.',SG+IL,['P4-S17'])

I(478,'The manuscript vanishing-cycle complex is shifted','other',[(5,67,128),(5,296,306)],'suite exacte des cycles évanescents',
  T+'The manuscript defines Φman as the colimit of cohomology with support in the special fibre. Thus Φman=Cone(ΛXs→RΨΛ)[−1], whereas the usual RΦ is the unshifted cone. It gives the long exact specialization sequence, finite-coefficient local-to-global spectral sequence and a conditional ℓ-adic version.',
  'The derived formulation and name Φman are ours. The shift is forced by (1.9) and (2.5)–(2.6), not an alteration of the notation.')
C(802,478,[(5,67,85),(5,296,306)],r'\Phi^{i+1}_\nu',T+'Localization and filtered colimits give Φman→RΓ(Xs,Λν)→RΓ(X_Kbar,Λν)→Φman[1]; sheafwise Φman=Cone(Λ→RΨΛ)[−1].','proof sketched','A',
  'SGA7 I§2 and the conventional cone in Illusie2021 (1.1.2)–(1.1.4) establish the same construction with a different degree convention. All later degree comparisons in this dossier shift by one.',SG+IL,['P4-S17'], 'proof_audit.md §10; code/codex_computations.py, cone-index output.')
C(803,478,[(5,85,98)],'finis',T+'When the special and geometric generic cohomology groups are finite at each ν, the adjacent exact sequence makes each Φman^i_ν finite. Finite inverse systems are Mittag–Leffler, so inverse limit over ν preserves the displayed exact sequence.','proof sketched','E',
  'The finite-coefficient argument is valid. It does not by itself justify taking an ordinary inverse limit of étale sheaves; that separate caution is retained in C-SA13-805.',IL,['P4-S17'],'proof_audit.md §10: finite-group Mittag–Leffler reproof.')
C(804,478,[(5,100,118)],r'E_2^{pq}',T+'The local-to-global spectral sequence H^p(Xs,Φman^q_ν)⇒Φman^(p+q)_ν is obtained from the support complexes and their filtered colimit; the stalk construction is étale local on X.','proof sketched','A',
  'This is the hypercohomology form of the SGA7 I§2 construction. The properness assumption is used to identify its global target with the specialization cone.',SG+IL,['P4-S17'],'proof_audit.md §10: bounded-below hypercohomology and exact filtered colimits.')
C(805,478,[(5,118,128),(5,340,340)],'constructibles',T+'The proposed ℓ-adic sheaf spectral sequence requires constructibility and a compatible constructible ℓ-adic/Artin–Rees system; the author expressly declines to use the naive ordinary inverse-limit formulation.','open on the pages','B',
  'Deligne’s finiteness theory and the ℓ-adic nearby-cycle formalism supply the finiteness missing here. The precise modern object is a derived/adic constructible system, not the inverse limit interpreted without its topology. See Deligne SGA4½ Finitude3.2 and Illusie2021 §1.2.', ['P4_DeligneFinitude1977']+IL,['P4-S18'])

I(479,'Smooth comparison and the ramification multiplier','reading question',[(5,130,164)],'morphisme de transition',
  T+'Purity identifies degree-two special-fibre support cohomology with Λν(−1); pullback multiplies its generator by the ramification index. Cofinal tame ℓ-power ramification kills the direct limit. This proves smooth local acyclicity and the proper smooth comparison; general vanishing cycles are supported on the nonsmooth locus.',
  'The manuscript writes field degree, which needs perfect residue field/totally ramified finite changes. In the stated strictly henselian imperfect-residue setting this is a substantive gap, repaired by using the divisor ramification index and a cofinal killing argument.')
C(806,479,[(5,130,132)],r'\underline H',T+'For X/S smooth, the support sheaf H^i_Xs(Λν) vanishes for i≠2 and equals Λν(−1) for i=2.','stated without proof','E',
  'Relative purity gives this elementary smooth-pair case; absolute purity now holds by Riou2014 Th3.1.1. The literal i≠0 and the mismatched ν versus ν+1 must be checked on the scan.',PU,['P4-S19'])
C(807,479,[(5,136,136)],r'n_{\alpha\beta}',T+'The page identifies the transition on the codimension-one support class with [Kβ:Kα]. In general it is instead e(Sβ/Sα), the multiplicity in the pulled-back closed divisor.','false as stated','C',
  'The source comparison is the divisor-class functoriality in Riou2014 §2 and §3.1.3. A complete strictly henselian counterexample with separably closed imperfect k is R=k[[π]], L=K[u]/(u^p−πu−a), a∉k^p: [L:K]=p, residue degree p, ramification index1. Thus field degree and the actual multiplier differ. The smooth comparison theorem survives.',PU,['P4-S19'],'proof_audit.md §11 checks every hypothesis of the fierce-extension example; code/codex_computations.py checks distinct multipliers modulo an auxiliary prime.')
C(808,479,[(5,136,145)],r'\underline\Phi^i_\nu=0',T+'Cofinal extensions with arbitrarily ℓ-divisible ramification kill the degree-two support transition, so Φman vanishes at smooth points; for proper smooth X/S, specialization is an isomorphism, and generally SuppΦman lies in the nonsmooth locus.','proof sketched','A',
  'SGA7 I2.4 and Illusie2021 §1.2 give smooth local acyclicity and proper smooth comparison. The conclusion is valid after replacing the erroneous general field-degree multiplier by ramification.',SG+IL,['P4-S17','P4-S19'],'proof_audit.md §11: killing each finite-stage class by a further tame ℓ-power extension.')
C(809,479,[(5,149,164)],'purement locaux',T+'If the nonsmooth locus in Xs is finite, all higher cohomology of the supported vanishing-cycle sheaves vanishes and Φman^i_ν is the direct sum of their geometric stalks.','proved there','A',
  'This follows from the same hypercohomology construction and the zero-dimensional separably closed support. The geometric stalks, rather than unqualified arithmetic point fibres, are essential.',SG,['P4-S17'],'proof_audit.md §10: finite support and spectral-sequence collapse.')

I(480,'Inertia actions and the finite filtration argument','self-flagged step',[(5,168,174)],'essentiellement triviale',
  T+'The specialization sequence and local-to-global spectral sequence are equivariant, with trivial inertia action on special-fibre cohomology. An open subgroup trivial on all coefficient cycle sheaves acts unipotently on the global groups; it does not imply unipotence for the whole inertia group.',
  'The inserted non! is retained. The formal filtration lemma supplies the precise exponent, while the existence of one subgroup uniform in degree and coefficient level needs the later geometric theorem.')
C(810,480,[(5,168,174)],'suite spectrale de $I$-modules',T+'The constructions by finite Galois covers give compatible continuous I-actions on local cycles, global cycles and specialization; inertia acts trivially on H*(Xs,Λν).','proof sketched','A',
  'The Galois-equivariant formulation is explicit in Illusie2021 §1.1–1.2. It is not an assertion that full inertia acts trivially on nearby cycles.',SG+IL,['P4-S17'])
C(811,480,[(5,172,174)],'ouvert fixe',T+'If I′ acts trivially on the terms of a first-quadrant E2 spectral sequence in total degree i, it acts trivially on the associated graded of a filtration of length at most i+1 of the abutment; hence (g−1)^(i+1)=0 for g∈I′.','proof sketched','E',
  'The filtration inference is elementary and valid for I′. Deligne/Gabber’s monodromy theorem, as stated in Illusie2021 Th2.3, supplies such unipotence in greater generality. Full-I unipotence does not follow from an open subgroup.',IL,['P4-S20'],'proof_audit.md §12; code/codex_computations.py exact Jordan-filtration tests.')

I(481,'Open generic fibres and tame invariants','other',[(5,176,247)],'Restriction aux revêtements modérément ramifiés',
  T+'For an open U⊂Xη with X proper, replace support in Xs by X−U and compare H*(Xs) with H*(U_Kbar). Restricting the finite extensions to the maximal tame extension computes wild-inertia invariants. Continuous actions of a pro-p group on finite-rank Zℓ-modules have finite image.',
  'The missing geometric bar on U and the self-referential definition of Yα are reading alarms. The pro-p assertion uses finite generation and ℓ≠p.')
C(812,481,[(5,176,193)],r'\Phi^i_\nu=\varinjlim',T+'For Y=X−U, the filtered support complexes RΓ_Yα(Xα,Λν) give a specialization cone whose generic term is RΓ(U_Kbar,Λν); their restriction to Xs yields the corresponding local spectral sequence.','proof sketched','A',
  'This is the open-generic-fibre form of nearby cycles RΨ(Rj*Λ), consistent with IllusieLog2002 §8.4 for open log strata. The literal H*(U) in the page omits a geometric base change.',SG+IL,['P4-S17'])
C(813,481,[(5,200,238)],r'H^p(P',T+'For wild inertia P, a pro-p group, and discrete ℓ-primary coefficients, H^a(P,M)=0 for a>0. Hochschild–Serre therefore identifies H*(U_Kt,Λν) with H*(U_Kbar,Λν)^P; taking K(π^(1/n)), (n,p)=1, is cofinal in the tame tower.','proved there','E',
  'Exactness follows by finite-quotient averaging and continuous-cohomology limits. The tame definition and exact P-invariants are recorded in Illusie2021 §2.1 and IllusieLog2002 §8.4.',IL+['P4_IllusieLog2002'],['P4-S20'],'proof_audit.md §12: continuous averaging, not an assertion about ℓ=p.')
C(814,481,[(5,239,247)],r'$P$',T+'A continuous pro-p action on a finitely generated Zℓ-module, ℓ≠p, has finite image and is killed after a finite extension. The same exact-invariant construction works for a closed normal pro-prime-to-ℓ subgroup with pro-ℓ quotient.', 'proof sketched','E',
  'Reduction modulo ℓ (modulo4 when ℓ=2) leaves a pro-ℓ congruence kernel; its intersection with a pro-p image is trivial. The torsion submodule is finite and can first be killed. The finiteness hypothesis is indispensable.',IL,['P4-S20'],'proof_audit.md §12: finite image including torsion and the ℓ=2 congruence adjustment.')

I(482,'Nearby-cycle Leray sequences and their relation to Φ','other',[(5,254,340)],'suite spectrale',
  T+'The alternative construction takes the colimit of R^qgα*Λν restricted to the special fibre, producing nearby-cycle sheaves Ψ^q_ν and a proper Leray spectral sequence to H*(U_Kbar). It also has a tame variant and explains the shifted exact relationship with Φman.',
  'After nontrivial finite base change the composite gα need not be an immersion. ℓ-adic constructibility is a separate theorem, not justified merely by defining the torsion sheaves.')
C(815,482,[(5,254,296)],r'R^qg',T+'For gα:U_Kα→X, filtered colimits of R^qgα*Λν restricted to Xs define Ψ^q_ν; proper base change and Leray give H^p(Xs,Ψ^q_ν)⇒H^(p+q)(U_Kbar,Λν).','proof sketched','A',
  'The construction matches SGA7 I§2 and the proper nearby-cycle comparison of Illusie2021 §1.2. The map gα is a composite, not generally an immersion as the page calls it.',SG+IL,['P4-S17'])
C(816,482,[(5,296,308)],r'\Psi',T+'There is 0→Φman^0→ΛXs→Ψ^0→Φman^1→0 and, for i≥1, Ψ^i≅Φman^(i+1); all identifications and spectral sequences are Galois equivariant.','proved there','A',
  'This is exactly the cohomology sequence of Φman→Λ→RΨ. The usual RΦ conventions in Illusie2021 §1.1 confirm the one-degree translation.',SG+IL,['P4-S17'],'proof_audit.md §10; cone-index computation.')
C(817,482,[(5,315,340)],r'\mathrm{tame}',T+'The tame Ψ sheaves are the analogous colimit over extensions of degree prime to p, equal to P-invariants of full nearby cycles. The ℓ-adic version requires the constructible-system theorem.', 'proof sketched','A',
  'SGA7 I§3 and Illusie2021 §2.1 establish the tame definition. A displayed coprimality with ℓ instead of p is a reading alarm, not a new tower convention.',SG+IL,['P4-S18','P4-S20'])

I(483,'Normal-crossing geometric monodromy theorem','unproved claim',[(5,345,382)],'croisements normaux',
  T+'For a regular proper model X with strict normal-crossing boundary X−U and the stated purity and finiteness hypotheses, tame cohomology is finitely generated and some open I′ acts unipotently on H^i with exponent i+1. The prime-to-p part of the lcm of positive vertical multiplicities specifies a subgroup; the filtration is Galois stable.',
  'The page promises the later local calculation. Triviality on graded pieces is for I′, not full I. The word pure for an integral filtration needs an independent saturation argument and is not supplied by the spectral sequence alone.')
C(818,483,[(5,345,375)],r'i+1',T+'Under the normal-crossing model, purity and finiteness assumptions of manuscript3.1, an open tame-inertia subgroup acts on H^i(U_Kbar,Zℓ)^P with (g−1)^(i+1)=0; at finite level the same bound holds on the corresponding tame cohomology.','stated without proof','A',
  'The construction is later in SGA7 I3.1–3.4, but the original printed I3.4 has an off-by-one q′ formula; it cannot certify a sharper incorrect bound. IllusieLog2002 (8.4.4.1) gives min(q+1, log rank), and Illusie2021 Th2.3 confirms i+1 in full generality.',SG+IL+['P4_IllusieLog2002'],['P4-S20'],'proof_audit.md §12 documents both the correct filtration proof and the printed-source error.')
C(819,483,[(5,356,382)],'filtration',T+'The spectral filtration is canonical and stable under the full arithmetic Galois group, while I′ acts trivially on its graded pieces. Its integral saturation or purity is an additional assertion and is not automatic for an arbitrary spectral sequence.', 'stated without proof','C',
  'Canonical equivariance follows functorially. Exact universal saturation of the specific manuscript filtration was not identified in the checked SGA7 I3.4/Illusie statements; a Qℓ filtration avoids that extra integral claim. This unresolved qualifier is retained rather than silently removed.',SG+IL,['P4-S20'],confidence='medium')
C(820,483,[(5,372,382)],'Griffiths', 'The page attributes an analogous complex-analytic geometric monodromy statement to Griffiths, with the same filtration interpretation.', 'stated without proof','F',
  'The analytic analogy is real, but this brief attribution does not identify an exact Griffiths theorem, date or publication. Searches of Griffiths monodromy and the later SGA7/Illusie bibliographies did not securely resolve the intended source; no priority is assigned.',IL,['P4-S20'],confidence='low')

I(484,'Resolution and compactification in the general monodromy argument','conjecture',[(5,386,403),(6,6,29)],'résolution',
  T+'Assuming resolution with a normal-crossing boundary and the relevant purity, the monodromy result extends from regular models to smooth quasi-projective generic fibres, then by compactification and dévissage to separated finite-type schemes and compact support. The text distinguishes the characteristic-zero theorem from positive-characteristic resolution assumptions and records special low-degree cases.',
  'Modern alterations and purity prove the cohomological conclusion without proving the asserted general resolution hypothesis. The weaker exponent3 stated for general H1 was later improved to2.')
C(821,484,[(5,386,403),(6,6,12)],'quasi-projectif',T+'Resolution of a proper compactification with normal-crossing boundary and purity imply quasi-unipotence with exponent i+1 on the cohomology of smooth quasi-projective generic fibres; Nagata compactification extends the setup to separated finite type.', 'proof sketched','B',
  'Illusie2021 Th2.3 gives the cohomological theorem for every separated finite-type generic fibre; §7 uses alterations and Gabber’s argument, so no general positive-characteristic resolution theorem is inferred.',IL,['P4-S20','P4-S21'])
C(822,484,[(6,9,20)],r'H^i_!',T+'By dévissage through smooth strata and localization, cohomology and cohomology with compact support are finite and have quasi-unipotent inertia under the draft’s hypotheses. Degreewise partial purity suffices where only the corresponding low-degree terms enter.', 'proof sketched','B',
  'The finiteness and monodromy conclusions are established by Deligne’s finiteness theory and Illusie2021 Th2.3, including compact support. The historical partial-purity reduction is kept separate from today’s absolute purity theorem.',IL+['P4_DeligneFinitude1977','P4_Riou2014'],['P4-S18','P4-S20','P4-S21'])
C(823,484,[(6,23,29)],"d'échelon 2",T+'The author gives H1 unipotence exponent2 for smooth curves, exponent3 for arbitrary finite-type generic fibres, and exponent2 in the normal case, after passage to suitable open inertia.', 'stated without proof','A',
  'SGA7 I3.5 and I3.7 establish exponent2 for H1, including the general finite-type case in the published statement. Thus the manuscript’s exponent3 is a weaker bound, not a refuted one.',SG+IL,['P4-S20'])

# K34-06: purity, Gysin, the normal-crossing algebra, and the Kummer maps.
I(485,'Cohomological purity and its historical conjectural status','conjecture',[(6,40,86)],'pureté cohomologique',
  'For a regular X, the draft defines purity by requiring support cohomology of every regular codimension-one pair in every étale neighbourhood to occur in degree2, equivalently the complement direct images only in degrees0,1. It conjectures this for all regular schemes, records then-known cases, and notes étale/local regular-subscheme stability.',
  'The historical assertion that mixed-characteristic purity was not proved describes the time of writing. It is not a present open problem. The strict-local complement printed Z−Y is empty and must be checked against Y−Z.')
C(824,485,[(6,40,68)],r'i\ne 0,1', 'For a regular divisor Z⊂Y in the stated local setting, localization identifies purity H^i_Z(Λ)=0 for i≠2 with R^ij*Λ=0 for i≠0,1; the definition up to degree1 is vacuous. The condition is étale local.', 'proved there','E',
  'The equivalence follows from the localization triangle and regularity/normality for j*Λ=Λ. Riou2014 Cor3.1.3 supplies the now-unconditional divisor formula.',PU,['P4-S19'],'proof_audit.md §13: localization indices.')
C(825,485,[(6,74,86)],'on conjecture', 'Every regular scheme should satisfy prime-to-residue-characteristic absolute cohomological purity, including mixed characteristic; the text only knows smooth pairs and excellent characteristic-zero/conditional-resolution cases.', 'open on the pages','B',
  'Gabber’s absolute purity theorem resolves the conjecture for regular noetherian pairs and invertible torsion coefficients. Riou2014 Th3.1.1 gives the full statement and proof, following a new proof announced2005; it distinguishes Fujiwara’s published2002 proof of Gabber’s earlier theorem.',PU,['P4-S19'],date='Conjecture in the 1960s; Gabber proof exposed1994, Fujiwara publication2002 (backward reference); new Gabber proof announced2005, Riou exposition published2014.')
C(826,485,[(6,86,86)],'stable par localisation', 'The draft’s purity property is preserved by étale localization and by passage to a regular subscheme, since its definition already quantifies over the corresponding regular pairs.', 'proved there','E',
  'The quantifier argument is valid. Modern absolute purity makes the inheritance unconditional in the regular noetherian/invertible-coefficient category.',PU,['P4-S19'],'proof_audit.md §13: definition and regular-pair inheritance.')

I(486,'Purity in arbitrary codimension and Gysin classes','other',[(6,89,206)],'isom. canonique',
  'For a regular closed immersion Y⊂X of pure codimension d and invertible Λ=Z/n, absolute purity gives Ri!Λ=ΛY(−d)[−2d]. The draft constructs the resulting Gysin long exact sequence, the fundamental class, its projection formula and the divisor first Chern class.',
  'The local flag proof gives the vanishing; independence of choices and the canonical class are referred to SGA4/SGA5. Several displayed degrees, supports and twists in the transcription are inconsistent with the correctly stated long exact sequence.')
C(827,486,[(6,89,129)],r'\underline H^{2d}_Y', 'If X and Y are regular and Y has pure codimension d, the assumed codimension-one purity yields H^i_Y(ΛX)=0 for i≠2d and H^(2d)_Y(ΛX)=ΛY(−d), canonically after fixing the usual fundamental class.', 'proof sketched','B',
  'Riou2014 Th3.1.1 proves the exact regular-pair statement without a resolution hypothesis. The manuscript’s induction through a local regular flag gives the correct degree2d; its intermediate q=1, ΛY/ΛZ labels require repair.',PU,['P4-S19'],'proof_audit.md §13: regular flags and support spectral-sequence concentration.')
C(828,486,[(6,134,193)],r'H^{i-2d}', 'For F locally constant and n-torsion on X, purity identifies H^i_Y(X,F) with H^(i−2d)(Y,F(−d)); localization gives the displayed Gysin long exact sequence.', 'proved there','A',
  'This is the classical Gysin construction in the cited SGA4/5 theory; Riou2014 §2 and Th3.1.1 verify the modern formulation. The requirement that F be locally constant on X is retained.',PU,['P4-S19'],'proof_audit.md §13: coefficient and degree bookkeeping.')
C(829,486,[(6,146,166),(6,196,203)],r'\gamma(Y)', 'The image of1 under the supported fundamental-class map is γ(Y)∈H^(2d)(X,Λ(d)); restriction followed by Gysin is cup product with γ(Y). For d=1, γ(Y)=c1(OX(Y)), the Kummer boundary of the line-bundle class.', 'proof sketched','A',
  'Riou2014 §1.1, §2.1–2.2 and the purity normalization verify the fundamental-class and projection-formula statement. The composite on scan105 must start at H^(i−2d)(X,F(−d)), not the mismatched displayed degrees/twists.',PU,['P4-S19'],'proof_audit.md §13: projection formula and principal-divisor class.')

I(487,'The exterior algebra of a normal-crossing complement','unproved claim',[(6,216,355)],r'\bigwedge^p',
  'Let X be regular, D=ΣDi a strict normal-crossing divisor with regular irreducible components and j:X−D→X; n is invertible along D. R1j*Λ=⊕ΛDi(−1), and under purity the cup-product algebra R*j*Λ is the exterior algebra on R1, with its intersection-stratum formula.',
  'The deleted Čech route incorrectly starts from U=∪Ui; U is ∩Ui. The live replacement uses strict-local Kummer classes and induction. It does not retract the theorem.')
C(830,487,[(6,216,228),(6,335,360)],r'R^1f_*', 'For a strict normal-crossing divisor, local tame fundamental groups or Kummer theory give R1j*Λ≅⊕iΛDi(−1); this degree-one computation does not require the extra higher-cohomological purity assumption.', 'proof sketched','A',
  'SGA7 I3.1 records the local computation; Riou2014 Cor3.1.4 gives the full modern exterior-algebra result. The degree-one assertion is independently explained using strict-local units and divisor valuations.',SG+PU,['P4-S19','P4-S22'],'proof_audit.md §13: Kummer classes of the local equations.')
C(831,487,[(6,232,254),(6,343,355)],r'\bigwedge^p R^1', 'Assuming purity, cup product identifies Rqj*Λ with ∧q(R1j*Λ), hence with the direct sum of Λ(−q) supported on q-fold intersections of the components.', 'proof sketched','A',
  'The exact result is SGA7 I3.1 and, now without a separate purity assumption, Riou2014 Cor3.1.4. It requires strict normal crossings locally, not an arbitrary union of regular divisors.',SG+PU,['P4-S19','P4-S22'],'proof_audit.md §13; code/codex_computations.py checks exterior ranks and inductive decomposition.')
C(832,487,[(6,294,326)],r'U=\bigcup', 'The cancelled proof treats U=X−∪Di as the union of Ui=X−Di and tries to use a covering spectral sequence. The set-theoretic identity is false: U=∩Ui.', 'corrected by himself later','E',
  'The entire erroneous route is deleted and a strict-local argument begins at scan109 line335. No living Čech-cover claim is retained; this is a recorded withdrawal, not a new open problem.',PU,['P4-S19'],'proof_audit.md §13: elementary complement identity and the live replacement locator.')

I(488,'The Gysin induction and its admitted residue square','self-flagged step',[(6,360,515)],"Nous admettrons qu'on obtient ainsi",
  'The induction removes the last divisor. The Gysin map vanishes because its class is that of a principal divisor; restriction to the last-divisor stratum identifies the preceding generators. The author then admits the compatibility of cup product with the residue map in the second square, from which the exterior-algebra isomorphism follows.',
  'The needed residue formula can be proved after fixing the order of factors and the Kummer-boundary sign. The sentence about arbitrary locally constant F is safe for F extending over the strict-local X; it is false for unrestricted ramified F on U′.')
C(833,488,[(6,439,470)],r'\alpha_i', 'In the strict-local normal-crossing induction, for coefficients F extending from X, H*(U′,F)→H*(D′r,F) is the identification on the first r−1 Kummer generators. Since Dr is principal, the Gysin maps αi vanish and localization splits into the written short exact sequences.', 'proof sketched','A',
  'Riou2014 Cor3.1.4 and the projection formula justify the constant-coefficient argument. If the phrase locally constant F is read as allowing any sheaf on U′, an Artin–Schreier cover z^p−z=y/x of D(x)⊂Spec k[[x,y]] gives a counterexample: its pushforward has H0 rank1, while restriction to y=0 has rankp. Extension over X is a sufficient repair.',PU,['P4-S19','P4-S22'],'proof_audit.md §13 gives the principal-class proof and checks the scope counterexample.',confidence='high')
C(834,488,[(6,490,515)],'deuxième', 'The comparison of exterior-power and Gysin short exact sequences requires the residue identity for the Kummer class of the last equation and a class extending over U′. With compatible order/sign, residue takes this product to the restricted class; the five-lemma argument then gives the middle isomorphism.', 'open on the pages','B',
  'The admitted square is supplied by compatibility of the localization boundary with cup product and the divisor fundamental class. Riou2014 §4 records sign conventions and Cor3.1.3 describes the Kummer normalization; Cor3.1.4 proves the target theorem. The source uses an opposite Kummer torsor convention, so no unqualified sign is imported.',PU,['P4-S19','P4-S22'],'proof_audit.md §13: explicit residue normalization and graded-module boundary identity.')

I(489,'Taking roots of all boundary equations','other',[(6,519,574),(7,7,26)],r'm^p.\mathrm{id}',
  'Adjoining an mth root of each local regular parameter, with m invertible, gives a regular root cover with normal-crossing boundary. Pullback multiplies divisor classes by m and degree-q exterior cohomology by m^q; if n divides m, it kills every positive-degree Λ=Z/n cohomology class.',
  'The torsor group is μm^r on the complement; the missing exponent r in the next page is a mathematical reading alarm. Root-cover regularity uses a normal-crossing parameter system.')
C(835,489,[(6,519,540)],r'p^*(D_i)=m\Delta_i', 'For a regular scheme with strict normal-crossing local equations ai and m invertible, adjoining roots Ti^m=ai produces a regular scheme X′; the divisors Δi=(Ti=0) meet normally and p*Di=mΔi, with complement p^−1U.', 'stated without proof','E',
  'This is the local root construction behind absolute Abhyankar theory and the tame computation in SGA7 I3.1–3.3. Regularity can be checked directly in regular local parameters; no smoothness of X over a field is needed.',SG+['P4_IllusieLog2002'],['P4-S22'],'proof_audit.md §14: local regular-parameter proof.')
C(836,489,[(6,543,574),(7,7,13)],r'm^p.\mathrm{id}', 'Under the Kummer/exterior identifications, root pullback is multiplication by m in degree1 and by m^q in degreeq. Thus a further root cover with n|m kills H^q(U,Z/n) for every q>0 in the strict-local setting.', 'proved there','A',
  'The root transition is the calculation in SGA7 I3.1 underlying the tame formula; IllusieLog2002 (6.8.3) records the same degreewise multiplication. The vanishing applies to positive degree, not H0.',SG+['P4_IllusieLog2002'],['P4-S22'],'proof_audit.md §14; code/codex_computations.py exact exterior minors and modular killing.')
C(837,489,[(7,14,26)],r'\mu_m', 'On the complement of r crossing components, the simultaneous root cover is a finite étale torsor under μm^r; its degree is m^r, not m when r>1.', 'proof sketched','A',
  'The r independent roots give the product group. SGA7 I3.1 and the subsequent manuscript G(m)=μm^r formula confirm that the earlier missing power is a transcription/notation alarm.',SG,['P4-S22'],'proof_audit.md §14; rank and degree computation.')

# K34-07: the tame Kummer tower and its local-to-global applications.
I(490,'The acyclic simultaneous Kummer tower','other',[(7,32,131)],r'U(\infty)',
  'For a strictly henselian regular local ring A and regular parameters a1,…,ar, the inverse limit of the complements in all prime-to-p simultaneous root covers is an affine pro-étale G-torsor, G=∏ℓ≠p Zℓ(1)^r. Under purity on all root covers it has H0=Λ and no positive-degree prime-to-p torsion cohomology.',
  'The cohomology is ordinary étale cohomology of the affine inverse limit, computed by continuity. Calling it acyclic only concerns these coefficients; no assertion about p-primary cohomology is made.')
C(838,490,[(7,32,96)],r'\mu_m(X)^r=G(m)', 'The regular-parameter root covers are connected finite étale μm^r-torsors over U, their transition maps are compatible, and their affine inverse limit carries the profinite group G=∏ℓ≠p Zℓ(1)^r.', 'proved there','A',
  'This is the local Kummer tower behind SGA7 I3.1–3.3 and IllusieLog2002 §§4,6.8. Connectedness follows from the successive root rings being local regular domains; the product group is essential.',SG+['P4_IllusieLog2002'],['P4-S22'],'proof_audit.md §14: regularity, connectedness and group identification.')
C(839,490,[(7,92,131)],r'H^0(U(\infty),\Lambda)', 'If purity holds on X and all X(m), continuity and the transition multiplication imply H^q(U∞,Z/n)=0 for q>0 and H0(U∞,Z/n)=Z/n, where (n,p)=1.', 'proved there','A',
  'The argument is valid: every positive-degree finite-stage class is killed at a stage divisible by nm. Absolute purity now supplies the stated premise. It does not mean that each finite root cover is cohomologically acyclic.',SG+PU,['P4-S19','P4-S22'],'proof_audit.md §14; modular tower transition computation.')

I(491,'Associated profinite covers and their cohomology','other',[(7,141,237)],r'H^*(H,\Lambda)',
  'For a continuous homomorphism φ:G→Γ with closed kernel H, the associated Γ-cover has cohomology the continuous induced Γ-algebra from H*(H,Λ). The image of G acts trivially because conjugation by the abelian G is trivial. If that image is normal and Λ is nonzero, it is exactly the kernel of the Γ-action.',
  'For infinite Γ/image, induced means continuous locally constant functions, not all functions. The exact-kernel statement needs n>1, supplied later in4.15 but absent in4.11.')
C(840,491,[(7,141,222)],r'\mathbin{\times^', 'For H=ker(G→Γ), the associated pro-cover U′=U∞×^GΓ has H*(U′,Λ)≅Ind_cont^Γ_imG H*(H,Λ); Hochschild–Serre for U∞→U∞/H collapses because U∞ is acyclic.', 'proved there','A',
  'The local descent calculation underlies the SGA7 I3.3 tame stalk formula. Its profinite meaning is continuous induction on the coset space; arbitrary set-theoretic products would give the wrong H0 for an infinite profinite set.',SG+['P4_IllusieLog2002'],['P4-S22'],'proof_audit.md §14: finite-level descent followed by continuity.')
C(841,491,[(7,205,226)],'commutatif', 'The action of imG=G/H on H*(U∞/H,Λ) corresponds to conjugation on H and is therefore trivial, because G is abelian.', 'proved there','E',
  'Equivariant Hochschild–Serre identifies the action, so the claim follows. Triviality is specific to this abelian Kummer tower and does not hold for an arbitrary profinite extension.',SG,['P4-S22'],'proof_audit.md §14: conjugation action on group-cohomology resolution.')
C(842,491,[(7,231,234)],r'n', 'If imG is normal in Γ and Λ=Z/n with n>1, the kernel of Γ on the cohomology of U′ is imG; H0 already detects every nontrivial coset by locally constant characteristic functions. For n=1 the exact-kernel statement fails unless imG=Γ.', 'proof sketched','E',
  'The proof by H0 verifies the repaired statement. The manuscript allows n=1 in4.8 but4.15 explicitly imposes n>1. This is a missing-quantifier issue in4.11, not an unresolved theorem.',SG,['P4-S22'],'proof_audit.md §14; finite-coset permutation checks including the zero coefficient ring.')
C(843,491,[(7,231,231)],r'\leq N', 'If the root covers satisfy the stated partial purity only through degreeN, the acyclicity and associated-cover computations remain valid in the corresponding range ≤N.', 'proof sketched','E',
  'The first-quadrant spectral-sequence argument is degreewise: terms beyond total degreeN are not needed. Modern full purity makes this historical truncation unnecessary, while preserving the valid reduction.',PU,['P4-S19','P4-S22'],'proof_audit.md §14: truncated spectral-sequence range.')

I(492,'Continuous cohomology and the multiplicity homomorphism','other',[(7,244,343)],r'\sum_1^r m_i\lambda_i',
  'A closed subgroup H of the prime-to-p Kummer lattice decomposes into free finite-rank Zℓ-submodules; its ℓ-primary continuous cohomology is the exterior algebra of Homcont(H,Λ). For the root tower of t=∏ai^mi, the classifying homomorphism is Σmiλi, with image gcd(mi)Γ and coefficient-independent inertia kernel.',
  'At least one multiplicity must be positive to assert a finite index. The all-zero monomial is allowed by the written mi≥0 but makes t=1 and the stated finite-index description inapplicable.')
C(844,492,[(7,253,275)],'module libre', 'Each H(ℓ) is a closed Zℓ-submodule of Zℓ^r and hence free of rank s≤r. For Λ=Z/ℓ^a, continuous group cohomology is ∧*Homcont(H,Λ), with Homcont(H,Λ)≅Λ^s.', 'proof sketched','E',
  'The completed group-ring Koszul resolution gives this exact result, including ℓ=2; the other prime factors have exact invariants. It is also the cohomological lattice in the SGA7 I3.3 tame formula.',SG,['P4-S22'],'proof_audit.md §14: continuous Koszul resolution; exterior-rank computation.')
C(845,492,[(7,280,332)],r'\varphi(\lambda_1,\ldots,\lambda_r)', 'The tower obtained by adjoining prime-to-p roots of t=∏ai^mi is the cover associated to the homomorphism (λi)↦Σmiλi from G to Γ=∏ℓ≠p Zℓ(1).', 'proved there','A',
  'The identity follows by multiplying chosen roots of the ai with exponents mi. SGA7 I3.3 and Illusie2021 (2.7.1) retain the multiplicity lattice and its torsion.',SG+IL,['P4-S22'],'proof_audit.md §14: root-character calculation.')
C(846,492,[(7,337,343)],'pgcd', 'If some mi>0, the image is dΓ, d=gcd(mi); its index is the prime-to-p part d′. For nonzero Λ prime to p, dΓ is exactly the kernel of the Γ-action on the associated-cover cohomology, independently of Λ.', 'proved there','A',
  'The integer Bézout identity computes the image, and H0 detects the quotient. The exact local formula agrees with SGA7 I3.3 and Illusie2021 (2.7.1). If all mi=0, image0 has infinite index and the finite d′ wording needs qualification.',SG+IL,['P4-S22'],'proof_audit.md §14; gcd-image calculations over finite quotients and all-zero edge case.')

I(493,'Global tame sheaves and the multiplicity lcm','reading question',[(7,349,435),(7,455,483)],'ppcm',
  'A global root tower for a function t invertible off a normal-crossing boundary gives sheaves on V(t). Strict-local calculations show that the subgroup determined by the lcm of the positive vertical multiplicities acts trivially. Proper cohomology and finite inverse limits then produce the Galois-stable unipotent filtration.',
  'Horizontal components have multiplicity0 and must be omitted from the lcm. The literal div(π) in the general t-setting is another notation alarm. The cancelled ordinary inverse-limit sheaf formula is replaced by the inverse limit of cohomology groups.')
C(847,493,[(7,349,435)],"G'", 'For regular X with strict normal-crossing D and t invertible on U=X−D, assume prime-to-p coefficients and purity on all strict-local root covers. If M is the lcm of the positive multiplicities in div(t), then MΓ acts trivially on all Rqf*Λ restricted to V(t).', 'proved there','A',
  'At every point of V(t) at least one vertical multiplicity is positive; its local gcd divides M. This proves the global subgroup claim. The manuscript’s unqualified lcm over all Di would be0 if horizontal components are included.',SG+IL,['P4-S22'],'proof_audit.md §14: local gcd divides global positive lcm.')
C(848,493,[(7,455,475)],'groupes finis', 'Constructibility of the tame sheaves gives finite E2 groups on the proper special fibre; inverse limit in ν yields E2^(p,q)=limν H^p(Xs,Ψt,ν^q) converging to H^(p+q)(U_Kbar,Zℓ)^P.', 'proof sketched','A',
  'Finite inverse systems justify the spectral passage. The live formula correctly retains the limit outside cohomology; it does not rely on cohomology commuting with a naive inverse-limit sheaf.',SG+['P4_DeligneFinitude1977'],['P4-S18','P4-S22'],'proof_audit.md §§10,12: finite inverse systems and bounded diagonals.')
C(849,493,[(7,480,483)],'gradué associé', 'Triviality of I′ on the tame sheaves gives triviality on E2 and then the associated graded of the abutment, with nilpotence exponent i+1 in total degreei; the spectral filtration is compatible with the full Galois action.', 'proved there','A',
  'This completes the draft’s announced3.2, subject to its hypotheses. Illusie2021 Th2.3 confirms the i+1 bound; the argument gives a filtration, not an automatic direct-sum splitting or saturated integral filtration.',SG+IL,['P4-S20','P4-S22'],'proof_audit.md §12; nilpotent-filtration computation.')

I(494,'Resolution-based constructibility and uniform monodromy of sheaves','unproved claim',[(7,493,593)],'AR-',
  T+'With U regular and a proper modification X′→X that is an isomorphism over U, X′ regular and boundary normal-crossing, the tame Ψν^q are constructible and form an AR-ℓ-adic system. For fixed q one open inertia subgroup works for every ν, with exponent q+1. The author conjectures the same kind of conclusion without regularity and for full nearby cycles.',
  'Resolution in all characteristics remains a stronger geometric hope than the now-established cohomological finiteness theorem. The cancelled quadratic exponent is not a surviving claim; the live proof uses trivial action on resolved E2 terms.')
C(850,494,[(7,493,503)],'sans restriction de caractéristique', 'Every regular generic open should admit the indicated proper regular modification with strict normal-crossing boundary over an excellent trait, in every characteristic; the characteristic-zero case is attributed to Hironaka.', 'open on the pages','C',
  'General positive-characteristic resolution in this strength is not supplied by the checked modern literature. Alterations suffice for the monodromy theorem but are not modifications that remain isomorphisms over U. Temkin’s contemporary work and the2024 height-reduction paper still distinguish local-uniformization/desingularization conjectures from proved altered versions.', ['P4_Temkin2024']+IL,['P4-S21'],confidence='high',date='Hironaka1964 for the characteristic-zero foundation; modern quasi-excellent refinements and alterations later; current literature searched19November2026.')
C(851,494,[(7,503,503)],'passage au complété', 'The text says excellence is harmless for the cohomological questions because one can pass from the trait to its completion.', 'stated without proof','C',
  'Completion reductions for these étale comparisons require the relevant comparison/regularity hypotheses; the sentence is not a proof of resolution descent or of arbitrary faithfully flat invariance. The exact unrestricted reduction as written was not identified in the sources checked; it is retained as a scoped gap.',SG+IL,['P4-S18','P4-S21'],confidence='medium')
C(852,494,[(7,519,527),(7,574,587)],'constructibles', 'Under the proper regular normal-crossing modification hypothesis, tame Ψν^q are constructible and their projective system is AR-ℓ-adic; proper direct images and the finite Leray spectral sequence preserve the constructible adic category.', 'proof sketched','A',
  'This is the resolution argument later appearing in Deligne’s SGA7 XIII2.3.1 in equal characteristic0; Deligne SGA4½ Finitude3.2 removes that characteristic restriction for torsion nearby-cycle constructibility. The manuscript’s stronger system statement must be interpreted in the adic category it expressly cites.', ['P4_SGA7XIII','P4_DeligneFinitude1977']+IL,['P4-S18'],'proof_audit.md §15: resolved Leray and finite filtration.')
C(853,494,[(7,535,571),(7,590,590)],r'q+1', 'With the same resolved model, one open subgroup, chosen from the positive vertical multiplicities, acts on tame Ψν^q with (g−1)^(q+1)=0 for every ν; the result passes to the adic object.', 'proof sketched','A',
  'The proof uses q+1 terms with trivial I′ action on a total-degree-q diagonal. The displayed coefficient Ψν^q inside Rqg′* must be Λν. The cancelled sum0..q(i+1) has value(q+1)(q+2)/2, not q(q+1)/2, but neither quadratic bound is needed by the live proof.',SG+IL,['P4-S18','P4-S20'],'proof_audit.md §15; code/codex_computations.py checks the discarded arithmetic and the live exponent.')
C(854,494,[(7,593,593)],'sans supposer', 'The author expects analogous constructibility, adic compatibility and quasi-unipotence for arbitrary U and full nearby-cycle sheaves, not merely their P-invariants.', 'open on the pages','B',
  'Deligne SGA4½ Finitude3.2 establishes torsion constructibility without the normal-crossing/resolution premise. Modern nearby-cycle formalism and monodromy establish the broader programme; the precise universal q+1 torsion bound is checked in Illusie2021 Th2.3 for global cohomology, and is not claimed to be a literal statement of Deligne3.2 about every stalk.', ['P4_DeligneFinitude1977']+IL,['P4-S18','P4-S20'],confidence='medium')

I(495,'The wild-inertia question','conjecture',[(7,596,603)],r'P$ \uline{opère}',
  T+'For a regular normal-crossing model with smooth reduced special components and prime-to-p multiplicities, the author asks whether wild inertia acts trivially on full nearby cycles. For proper X this would imply trivial action on global H*(U_Kbar); the degree-one case is promised later.',
  'The full-generic-fibre case matches the classical tame-reduction theorem. For an open U, the boundary must produce the corresponding log-smooth pair; smoothness of individual special components alone does not silently supply every horizontal-stratum condition.')
C(855,495,[(7,596,603)],r'\underline{\Psi}_\nu',T+'Under the draft’s normal-crossing and geometric smoothness conditions with all vertical multiplicities prime to p, does P act trivially on nearby-cycle sheaves?', 'open on the pages','B',
  'Rapoport–Zink1982 §§2–3 prove tameness for generalized semistable models with prime-to-p multiplicities. Nakayama1998 Th0.1,3.2 and3.4 generalize this to log-smooth reduction. IllusieLog2002 Cor8.4 treats RΨ(Rj*Λ) for the open trivial-log stratum. These precise hypotheses, including log smoothness for an open boundary, are retained.', ['P4_RapoportZink1982']+LO,['P4-S23'],date='Rapoport–Zink published1982; Nakayama received21February1995, accepted4March1997, publishedMay1998; Illusie lecturesJune1997, published2002.')
C(856,495,[(7,600,600)],'propre',T+'If X is proper and the full nearby-cycle sheaves have trivial wild inertia, P acts trivially on H*(U_Kbar,Λν); the same holds on the corresponding finite-rank ℓ-adic groups.', 'proof sketched','B',
  'Nakayama1998 Cor0.1.1 proves the proper full-generic-fibre assertion; IllusieLog2002 Cor8.4.3 includes the proper log-smooth open-stratum version. A filtration with P-trivial graded pieces splits as far as P-action is concerned by exact pro-p invariants on ℓ-primary coefficients.',LO,['P4-S23'],'proof_audit.md §§12,15: exact P-invariants eliminate finite-coefficient unipotent extensions.')

I(496,'Strict-local nearby-cycle stalks and the revised exposé heading','other',[(7,610,739),(8,12,43)],'localisé strict',
  T+'After the revised heading IV/V and the instruction to suppress coefficient indices, the next exposé computes Ψx^q as H^q(U′_Kbar,Λ), with X′ the strict localization at the geometric special point x and U′ the pullback of U. The tame version uses Kt. Strict localization is an affine inverse limit of pointed étale neighbourhoods.',
  'The final tame formula must use X′, not X. Scan132 contains two retained sheets, numbered V.3 and V.4; this is one scan identifier, not a duplicated assertion. Coefficient conventions continue from the preceding exposé.')
C(857,496,[(7,635,701),(7,720,733)],r'\overline U',T+'For a geometric special point x, (R^qΨΛ)x=H^q(U′×K Kbar,Λ), where X′ is the strict localization of X at x; replacing Kbar by Kt computes tame stalks.', 'proved there','A',
  'This is the exact nearby-cycle stalk formula, stated in SGA7 I§2 and Illusie2021 (1.1.4). The final manuscript tame formula’s unprimed X is inconsistent with the local construction.',SG+IL,['P4-S17'])
C(858,496,[(8,12,43)],r'\varprojlim', 'The strict localization X′ is the filtered inverse limit of affine pointed étale neighbourhoods, and its geometric generic cohomology is the colimit of theirs. If U is quasi-affine over Xη then U′_Kbar is quasi-affine; if the open immersion is affine then U′_Kbar is affine.', 'proof sketched','E',
  'These limit/affineness properties justify application of affine Lefschetz to the stalk. The stronger affine assertion explicitly needs the affine-open hypothesis, not merely any open in an affine scheme.',SG+['P4_PilloniStroh2014'],['P4-S17','P4-S24'],'proof_audit.md §16: affine inverse limits and the precise open hypothesis.')

# K34-08: affine bounds, depth, and the two localization triangles.
I(497,'The refined affine bound for nearby-cycle stalks','unproved claim',[(8,50,190)],r'n_x-\dim\overline',
  T+'For X of finite type, U→Xη affine and nx the largest generic dimension of a component through x, Ψx^q vanishes for q>nx−dim(closure{x}). The draft passes to the flat closure, chooses a residue transcendence basis and reduces to an affine situation over a strict-local trait.',
  'The argument requires the geometric generic base S1×S Kbar. The unbarred λ in the acyclicity sentence is false even when S1=S; original SGA7 I4.2 has the geometric base. The Φman bound has one extra degree.')
C(859,497,[(8,50,68)],r'i>n_x',T+'Under the affine-open hypothesis, continuity and affine Lefschetz give (Ψ^i)x=0 for i>nx. This is the first, unrefined stalk bound.', 'proved there','A',
  'SGA7 I4.2 proves the refined version; Pilloni–Stroh2014 Th1.1.2 is a modern affine Lefschetz statement. The argument does not use only quasi-affineness, which is weaker.',SG+['P4_PilloniStroh2014'],['P4-S24'],'proof_audit.md §16: affine-neighbourhood dimension bound.')
C(860,497,[(8,72,98)],'adhérence schématique', 'Replacing X by the schematic closure of its reduced generic fibre preserves the nearby-cycle complex, discards vertical components and permits the comparison nx=dimx Xs; the stalk bound then implies vanishing above dim OXs,x.', 'proof sketched','A',
  'Proper base change for the closed immersion of the generic closure, and invariance under nilpotents, justify the nearby-cycle reduction. The last formula reference on scan134 must compare2.1.2 with2.1.3, not2.1.1 with2.1.2.',SG+IL,['P4-S17','P4-S24'],'proof_audit.md §16: closed-immersion comparison and dimension formula.')
C(861,497,[(8,106,146)],'base de transc.', 'Choose r=trdegk k(x) functions whose residues form a transcendence basis; h:X→A^r_S sends x to the generic special-fibre point. Its strict localization S1 is a trait; after shrinking, X1/S1 has relative dimension≤n−r, so affine Lefschetz bounds the geometric generic stalk by n−r.', 'proof sketched','A',
  'This is the construction in the proof of SGA7 I4.2, original printedp14. It uses the local dimension formula and upper semicontinuity before shrinking; no finite Noether-normalization map from the cancelled attempt is assumed.',SG,['P4-S24'],'proof_audit.md §16: transcendence-basis reduction.')
C(862,497,[(8,144,166)],'pro-$p$-groupe', 'The proof claims λ=(S1)η has pro-p absolute Galois group and is prime-to-p acyclic. The needed and valid base is (S1)_Kbar; its pro-p Galois group permits the Leray degeneration used to descend the geometric stalk bound.', 'false as stated','A',
  'Original SGA7 I4.2 proof(a), printedp14, explicitly uses the geometric generic fibre S′_ηbar. For r=0 and S1=S, the literal field K has nontrivial tame Kummer H1(K,Z/ℓ), so it is not prime-to-p acyclic. This confirms a lost-bar alarm, not a failure of the refined theorem.',SG,['P4-S24'],'proof_audit.md §16: Kummer counterexample at r=0 and the published repaired base.')
C(863,497,[(8,170,190)],r'q>n_x',T+'For the affine-open setup, Ψx^q=0 for q>nx−dim closure{x}; Φman,x^q=0 for q>nx+1−dim closure{x}, q≥1. Globally Ψq=0 above dimXη and Φman^q=0 above dimXη+1.', 'proved there','A',
  'The nearby-cycle bound is SGA7 I4.2; the Φman version follows from C-SA13-816 and its low-degree exact sequence. For q=1 with a nonempty flat generic neighbourhood, the asserted upper bound does not wrongly remove the component defect.',SG,['P4-S24'],'proof_audit.md §§10,16; exact shifted-degree computation.')

I(498,'Support dimension and high-degree specialization','other',[(8,195,245)],r'n+d+1',
  T+'For proper X, write n=dimXη and d for the dimension of the nonsmooth locus in Xs. Combining stalk bounds with support dimension gives Φman^i=0 for i>n+d+1, provided the degree-zero term is controlled, for example X flat. Specialization is an isomorphism above that boundary and an epimorphism there. A duality corollary additionally needs a smooth pure-dimensional geometric generic fibre.',
  'The stated d≤n+1 condition handles q=0; it is not logically equivalent to dimXs≤n+1 unless an additional equality of supports is supplied. The generic smoothness missing from the corollary is acknowledged by the later cancelled comparison.')
C(864,498,[(8,195,229)],r'p+q\leq n+d+1',T+'For q≥1, dimSuppΦman^q≤min(d,n+1−q), hence nonzero H^p(Xs,Φman^q) has p+q≤n+d+1. The same conclusion for q=0 follows if d≤n+1, or from Φman^0=0 in the flat generic-closure setting.', 'proved there','A',
  'SGA7 I4.2–4.3 give the dimension/support mechanism. The elementary optimization of p≤2min(d,n+1−q) is correct and has been recomputed; the degree-zero exception is retained.',SG,['P4-S24'],'proof_audit.md §16; code/codex_computations.py exhaustive finite parameter checks and symbolic inequality proof.')
C(865,498,[(8,222,239)],r'i>n+d+1',T+'For proper X and the preceding support conditions, specialization H^i(Xs,Λ)→H^i(X_Kbar,Λ) is an isomorphism for i>n+d+1 and surjective for i=n+d+1. Inertia is trivial on generic cohomology in degrees≥n+d+1.', 'proved there','A',
  'SGA7 I4.3 is the published high-degree result. The exact boundary follows from Φman^i→H^i(Xs)→H^i(X_Kbar)→Φman^(i+1), with trivial inertia on the special fibre.',SG,['P4-S24'],'proof_audit.md §16: long-exact-sequence boundary check.')
C(866,498,[(8,242,245),(8,351,351)],r'i\notin[n-d,n+d]',T+'If additionally X_Kbar is smooth, proper and pure of dimensionn, duality gives trivial inertia on H^i outside [n−d,n+d]; for d=0 only the middle degree can have nontrivial monodromy.', 'stated without proof','A',
  'SGA7 I4.4 has the smooth-generic-fibre hypothesis needed for Poincaré duality. The manuscript scan138 says only previous hypotheses, while scan141’s cancelled comparison explicitly recognizes Xη smooth. The repaired statement is established; the unrestricted wording is not certified.',SG,['P4-S24'],'proof_audit.md §16: dual degrees2n−i and the invariant Tate twist.')

I(499,'The hyperplane alternative and the Kummer-dimension question','conjecture',[(8,248,281)],r'\leq n-1',
  'The projective argument cuts d+1 sufficiently general hyperplanes to avoid the bad locus and uses Gysin. The following question asks whether, for an arbitrary strictly local noetherian A of dimensionn and t∈mA, the prime-to-p root tower over D(t) has ℓ-cohomological dimension≤n−1.',
  'The hyperplane codimension is d+1. The completely arbitrary noetherian Kummer-tower question has a negative answer by a deduction from Gabber–Orgogozo’s nonexcellent examples; no general quasi-excellent refinement is silently identified with that counterexample.')
C(867,499,[(8,248,269)],'hyperplans', 'For projective X with the required smooth generic fibre, cut d+1 suitable hyperplanes so Y avoids the nonsmooth locus and is smooth over S. Gysin from H^i(Y_Kbar) to H^(i+2d+2)(X_Kbar)(d+1) is surjective for i≥n−d−1 and an isomorphism for i>n−d−1.', 'proof sketched','A',
  'This is the projective Lefschetz/duality alternative to SGA7 I4.3–4.4. The written codimensiond in X must be d+1, agreeing with the Gysin shift. The argument needs Bertini and the smooth-generic-fibre Gysin/Lefschetz setting.',SG+['P4_PilloniStroh2014'],['P4-S24'],'proof_audit.md §16; hyperplane-shift arithmetic.')
C(868,499,[(8,272,281)],'Est-il vrai', 'For every strictly local noetherian A of dimensionn, every t∈mA and prime ℓ invertible in A, is cdℓ(lim_m D(t^(1/m)))≤n−1, where m runs through integers prime to the residue characteristic?', 'open on the pages','B',
  'False in this unrestricted noetherian generality. Orgogozo2014 XVIII_B §§2.1–2.4 constructs a regular strictly henselian dimension2 A with principal U=D(F) and H3(U,Z/ℓ)≠0. Its root tower is a Γ-torsor with cdℓΓ=1. If the tower had cdℓ≤1, Cartan–Leray would force H3(U,Z/ℓ)=0. Thus its cdℓ is at least2. This last deduction is ours; the primary source proves the explicit finite-level example. It does not decide a suitably restricted quasi-excellent refinement.', ['P4_OrgogozoDimension2014','P4_IllusieDimension2014']+SG,['P4-S25'],'proof_audit.md §17 checks every ring/tower hypothesis and the two-column spectral-sequence contradiction; executable degree check included.',date='Gabber examples expounded in the2006–2008 seminar; Orgogozo published2014. The deduction for this manuscript’s root-tower question was made in this review19November2026.')

I(500,'Rectified étale depth and the global low-degree bound','unproved claim',[(8,289,327)],'profondeur étale rectifiée',
  'The convention is profet*_x=profet_x+dim closure{x}, with the closure taken in the relevant fibre. Under rectified depth≥m on both fibres, flat projectivity and the specified Lefschetz ingredients, cutting d+1 hyperplanes gives specialization isomorphisms in degrees<m−d−1 and injectivity at the boundary; equivalently Φman^i=0 for i≤m−d−1.',
  'The SGA1 XIV citation is a reading alarm for SGA2 XIV. The diagram gives injection, not surjection, at the low-degree boundary. Local depth is different from the rectified global infimum.')
C(869,500,[(8,289,302)],r'\operatorname{prof\,et}_x^{*}', 'Rectified étale depth at x in a fibre is profet_x plus dim closure{x} in that fibre; the depth bound is imposed at every point. The generic condition depends only on the geometric generic fibre.', 'stated without proof','A',
  'SGA2 XIV is the intended source, as confirmed by the explicit SGA2 XIV references in original SGA7 I4.5 and Illusie2003 §2.6. The closure-dimension term must be retained in comparisons with later manuscript inequalities.',SG+['P4_Illusie2003'],['P4-S26'])
C(870,500,[(8,303,310)],r'i<m-d-1', 'Under the stated rectified-depth and global Lefschetz assumptions, restriction from either fibre to the smooth complete intersection Y of codimensiond+1 is an isomorphism for i<m−d−1 and injective for i=m−d−1.', 'stated without proof','A',
  'This is the conditional SGA2 XIV global Lefschetz application written on the page. Modern affine Lefschetz and the depth theory supply analogous results under their explicit finiteness/hypothesis settings; the draft does not prove its cited theorem here.',SG+['P4_PilloniStroh2014','P4_Illusie2003'],['P4-S24','P4-S26'])
C(871,500,[(8,310,327)],r'\Phi^i_{', 'If both restriction maps in the specialization square are isomorphisms below a and injective at a=m−d−1, and the smooth section specialization is an isomorphism, then specialization for X is an isomorphism belowa and injective ata; consequently Φman^i=0 for i≤a.', 'proved there','E',
  'The low-degree boundary inference is a correct diagram chase followed by the shifted cone long exact sequence. It is independent of the unresolved historical proof prerequisites for the two restriction maps.',SG,['P4-S26'],'proof_audit.md §18: boundary diagram chase and cone degree.')

I(501,'The local-complete-intersection improvement and the pinching example','unproved claim',[(8,332,362)],'intersection complète',
  'For flat projective X with lci special fibre of pure dimensionn, the draft takes rectified depthm=n and expects an improved low-degree vanishing. It separately gives a flat pinching example with m=n=1,d=0 where Φman^1≠0, showing that the depth condition alone does not give the extra degree.',
  'The cancelled version is not counted as a second theorem. The pinching joins one closed-fibre point from each of two P1_S components; generic components remain separate, and H0 specialization is diagonal. The example’s special fibre can have embedded structure and is not asserted lci.')
C(872,501,[(8,332,356)],r'm=n', 'For a flat projective family with lci special fibre pure of dimensionn, the generic fibre is lci and both fibres have rectified étale depth≥n. The stronger expected vanishing is Φman^i=0 for i≤n−d under the further local Lefschetz inputs.', 'open on the pages','B',
  'The depth mechanism is SGA7 I4.5–4.7 in characteristic0. Illusie2003 Cor2.7 and2.10 prove perversity for flat relative lci schemes and isolated-singularity concentration/freeness over a general trait with ℓ invertible. For nonisolated support, perverse support/cosupport gives the corresponding lower bound; this is a modern reconstruction, not a literal statement that the page proves it.',SG+['P4_Illusie2003'],['P4-S26'],'proof_audit.md §18 distinguishes local lci depth from the weaker fibre-depth hypothesis.')
C(873,501,[(8,359,362)],r'\mathbb P^1_S\amalg\mathbb P^1_S', 'Pinch a k-rational special point on each of two copies of P1_S to one point. The resulting proper flat family has pure one-dimensional fibres, rectified fibre depth≥1 and isolated nonsmooth special point, but H0(Xs,Λ)=Λ→H0(X_Kbar,Λ)=Λ² is diagonal, so Φman^1 contains a nonzero copy ofΛ.', 'proof sketched','A',
  'The manuscript itself supplies the counterexample. The local pinching ring R[x]×_k R[y] is torsion-free over the DVR, hence flat; its generic fibre is the disjoint union. Its closed fibre is connected and has no zero-dimensional irreducible component, though an embedded nilpotent at the join explains why it is not a relative lci. The displayed H^(0|1) must be H0.',SG,['P4-S26'],'proof_audit.md §18 verifies the affine pinching model, depth bound and H0 calculation; code/codex_computations.py checks diagonal cokernels.')

I(502,'Local Lefschetz prerequisites','self-flagged step',[(8,367,373)],'Lefschetz local',
  'The author seeks local vanishing statements implying the preceding global results without projectivity, using SGA2 XIV4.5. The text expressly assumes purity, resolution and local affine Lefschetz, and reports characteristic-zero or severe low-dimensional equal-characteristic availability.',
  'These are historical proof dependencies. Modern purity and affine Lefschetz remove several of them; general resolution itself is not thereby solved.')
C(874,502,[(8,367,373)],'ingrédients', 'The announced local Lefschetz application is conditional on the enumerated purity, resolution and local affine Lefschetz inputs; it is not a proof in arbitrary characteristic on these pages.', 'open on the pages','B',
  'Riou2014 Th3.1.1 settles purity, Pilloni–Stroh2014 Th1.1.2 gives Gabber’s affine Lefschetz theorem, and Illusie2003 §§2.6–2.10 proves the relevant depth/lci vanishing over general traits. These exact cohomological statements replace the historical restriction without claiming arbitrary resolution.',PU+['P4_PilloniStroh2014','P4_Illusie2003'],['P4-S19','P4-S24','P4-S26'])

I(503,'The five local schemes and equivariant cohomology','other',[(8,380,469)],r'V_s=V\times_S\{s\}',
  T+'Let X′ be the strict localization at x and V=X′−{x}. The five objects Vs,V,Vη,V_Kbar and Vbar=V×S Sbar organize the local topology. Sbar is the normalization in Kbar; its special residue extension is purely inseparable. Inertia acts on Vbar over V and trivially on the special étale topos.',
  'The equivalence of special-fibre étale topoi is not an assertion that all the displayed schemes are isomorphic. The manuscript’s derived category is interpreted as continuous/admissible inertia modules.')
C(875,503,[(8,380,429)],r'\bar V=V\times_S\bar S', 'The normalization Sbar is the inverse limit of the finite-extension normalizations; Vbar is the corresponding inverse limit. Its generic open is V_Kbar and its special fibre induces the same étale topos as Vs by a purely inseparable residue change.', 'proved there','A',
  'The same local arrangement is used in original SGA7 I4.5. Continuity and topological invariance identify étale cohomology, not the underlying schemes or reduced structures.',SG,['P4-S17','P4-S26'])
C(876,503,[(8,434,458)],r'i\geq2', 'Since x lies in the special fibre, V_Kbar=X′_Kbar. Thus Φman,x^i≅H^(i−1)(V_Kbar,Λ) for i≥2, with 0→Φman,x^0→Λ→H0(V_Kbar,Λ)→Φman,x^1→0.', 'proved there','A',
  'This is a second explicit manuscript confirmation of the shifted convention, following the strict-local stalk calculation and the cone triangle. It is not usual RΦ in the same degree.',SG+IL,['P4-S17'],'proof_audit.md §10; cone-index check.')
C(877,503,[(8,467,469)],'admissible', 'The inertia action on Vbar is by V-automorphisms; on its purely inseparable special residue fibre it is trivial. Derived cohomology may therefore be formed in the category of discrete continuous/admissible Λ[I]-modules, with the ordinary complex recovered by forgetting I.', 'proof sketched','A',
  'This is the equivariant nearby-cycle formalism of SGA7 XIII and Illusie2021 §1.1. The adjective admissible must retain the continuous-action condition, not an arbitrary algebraic group-ring module category.', ['P4_SGA7XIII']+IL,['P4-S17','P4-S26'])

I(504,'Localization triangle A and the missing uniform vanishing hypothesis','self-flagged step',[(8,469,534)],r'H^i(V_s,\underline\Phi',
  'Triangle A relates the support complex on the punctured special fibre, cohomology of Vbar and cohomology of V_Kbar. The low-degree comparison requires Φman^i to vanish throughout Vs for i<m. Vanishing only at the omitted closed point x cannot imply vanishing of cohomology on Vs.',
  'Original SGA7 I4.5 proof(1) explicitly uses all generizations of x. The deleted word isolé is required for the final claim that the support complex vanishes on the punctured fibre; the support-at-x expressions must use Xbar rather than Vbar.')
C(878,504,[(8,469,486)],r'\mathbb R\Gamma(V_s,\underline\Phi', 'Localization for the generic open in Vbar gives the equivariant triangle RΓ(Vs,Φman)→RΓ(Vbar,Λ)→RΓ(V_Kbar,Λ)→; forgetting inertia gives triangle A′.', 'proved there','A',
  'The support complex is the manuscript Φman, not usual RΦ. The construction matches the local comparison in original SGA7 I4.5 and the derived formalism of XIII.',SG+['P4_SGA7XIII'],['P4-S17','P4-S26'],'proof_audit.md §19: localization triangle and shift.')
C(879,504,[(8,491,505)],r'(\Phi^i_\nu)_{\bar x}=0', 'The page infers H^i(Vs,Φman)=0 from vanishing of the stalk at x for i<m. The valid sufficient hypothesis is vanishing of all these sheaves on the punctured special fibre Vs. Under that uniform hypothesis, H^i(Vbar)→H^i(V_Kbar) is an isomorphism for i<m−1 and injective for i≤m−1.', 'false as stated','A',
  'Original SGA7 I4.5 proof(1), printedp15, explicitly requires vanishing at every generization in the punctured special fibre. A stalk at x gives no information on a disjoint punctured support. The repaired low-degree inference is an elementary hypercohomology and long-exact-sequence argument.',SG,['P4-S26'],'proof_audit.md §19 proves the repaired statement and gives a constructible-sheaf countermodel to the literal logical inference.')
C(880,504,[(8,509,519)],r'H^i_{\bar x}', 'With uniform punctured-fibre vanishing, the support-at-x comparison identifies H^i_x(Xbar,Λ) with Φman,x^i in the stated low range, using H^i_x(Xbar) and reduced H^(i−1)(Vbar); support is in Xbar, not in Vbar which omitsx.', 'proof sketched','A',
  'This is the comparison used in original SGA7 I4.5 proof(1). The margin contains three independent notation alarms: Xbar versus Vbar, X(m) versus V(m), and the reduced cohomological shift.',SG,['P4-S26'],'proof_audit.md §19: reduced localization cohomology including degrees0,1.')
C(881,504,[(8,521,534)],'non lissité', 'If x is an isolated nonsmooth point along the special fibre, the support complex on Vs vanishes, so RΓ(Vbar,Λ)→RΓ(V_Kbar,Λ) is an equivariant quasi-isomorphism. This does not follow merely because x is a nonsmooth point.', 'proof sketched','A',
  'SGA7 I4.5 hypothesis(a) and its proof confirm isolatedness. The deleted isolé in the transcription must be inspected on the manuscript scan; it cannot be dropped from the mathematical hypothesis.',SG,['P4-S26'],'proof_audit.md §19: support exclusion on the punctured special fibre.')

I(505,'Localization triangle B is a different triangle','other',[(8,536,557)],r'\mathrm{triv}',
  'Triangle B comes from extension by zero of the constant sheaf on the geometric generic open: RΓ(Vbar,j!Λ)→RΓ(Vbar,Λ)→RΓ(Vs,Λ)^triv→. This differs from triangle A, whose first term is cohomology with support in the special fibre.',
  'The notation for the extended sheaf is reconstructed as j!Λ from its displayed triangle. Neither this extension-by-zero complex nor support cohomology is replaced by the other.')
C(882,505,[(8,536,557)],r'\mathrm{triv}', 'The open/closed localization sequence 0→j!Λ→Λ→i*Λ→0 on Vbar yields the equivariant triangle B, with special-fibre cohomology carrying trivial inertia; forgetting inertia gives B′.', 'proved there','A',
  'This is the standard second localization triangle, compatible with SGA7 XIII’s continuous equivariant formalism. Distinguishing it from triangle A prevents an incorrect interchange of j!, Rj* and Ri!.', ['P4_SGA7XIII']+IL,['P4-S17','P4-S26'],'proof_audit.md §19: the two exact triangles with all functors identified.')


def write():
    for name,new,threshold in [('items.json',items,477),('claims.json',claims,800)]:
        path=OUT/name
        old=json.loads(path.read_text()) if path.exists() else []
        # Allocated ranges belong solely to this authored extension.
        old=[x for x in old if int(x['id'].split('-')[-1])<threshold]
        path.write_text(json.dumps(old+new,ensure_ascii=False,indent=2)+'\n')
    print(f'Codex authored extension saved: {len(items)} items, {len(claims)} claims, {len(problems)} problems.')

if __name__=='__main__':
    write()
